from pathlib import Path
from typing import Any, Dict, List, Optional
from fastapi import HTTPException, status

from app.config import DISCLAIMER_TEXT, SAVED_MODELS_DIR, WORKSPACE_DIR
from app.tasks.base import BaseMriTask, TaskInfo, TaskSetupGuide, TaskStatus

class AlzheimersTask(BaseMriTask):
    """
    Modular task for Alzheimer's Disease Brain MRI Structural Analysis.
    Currently in setup state: requires validated volumetric/slice dataset
    and dedicated model weights. Subject-level splits are mandatory to prevent leakage.
    """

    task_id = "alzheimers"
    name = "Alzheimer’s Disease MRI Classification"
    short_title = "Alzheimer’s Disease"
    category = "Neurodegenerative Disorders"
    tagline = "Structural T1-weighted MPRAGE volumetric analysis for hippocampal & cortical atrophy"
    description = (
        "Demonstrates deep learning approaches to identifying neurodegenerative patterns "
        "and progressive volumetric reduction in structural brain MRI. Emphasizes strict "
        "subject-level partitioning to prevent slice-level data leakage across patient scans."
    )
    supported_scan_types = ["MRI"]
    required_sequences = ["3D T1-weighted MPRAGE", "High-Resolution Coronal T1"]
    supported_orientations = ["Coronal", "Sagittal", "Axial"]
    supported_formats = [".jpg", ".jpeg", ".png"]
    limitations = [
        "Dataset & Model Setup Required: This task is currently unconfigured. No inference allowed.",
        "Clinical diagnosis of Alzheimer's requires comprehensive neuropsychological testing, amyloid/tau PET, and CSF biomarkers.",
        "T1-weighted structural atrophy patterns can overlap with frontotemporal lobar degeneration, vascular dementia, and normal aging.",
        "Models trained without subject-level splitting exhibit severe data leakage and inflated, false generalizability.",
    ]
    disclaimer = DISCLAIMER_TEXT

    def __init__(self):
        self.model_path = SAVED_MODELS_DIR / "axonova_alzheimers_best.keras"
        self.dataset_dir = WORKSPACE_DIR / "dataset" / "alzheimers"

    def is_ready(self) -> bool:
        return self.model_path.exists() and self.dataset_dir.exists()

    def get_status(self) -> TaskStatus:
        return "ready" if self.is_ready() else "setup_required"

    def get_class_labels(self) -> List[str]:
        # Do NOT invent classes if not loaded from real model checkpoint
        return []

    def get_setup_guide(self) -> TaskSetupGuide:
        return TaskSetupGuide(
            recommended_datasets=[
                "Alzheimer's Disease Neuroimaging Initiative (ADNI) - adni.loni.usc.edu",
                "Open Access Series of Imaging Studies (OASIS-1 / OASIS-3) - oasis-brains.org",
                "Kaggle Alzheimer's MRI 4-Class Preprocessed Dataset (Research Baseline)",
            ],
            required_sequences=["3D T1-weighted MPRAGE (1mm isotropic recommended)"],
            split_policy=(
                "STRICT SUBJECT-LEVEL SPLIT: Every individual subject/patient must have all their "
                "slices and longitudinal sessions assigned exclusively to either the training set OR "
                "the test set. Random slice-level partitioning causes severe data leakage."
            ),
            target_classes=[
                "Cognitively Normal (CN)",
                "Mild Cognitive Impairment (MCI)",
                "Alzheimer's Disease (AD)",
            ],
            expected_model_path=str(self.model_path),
            expected_dataset_dir=str(self.dataset_dir),
            data_leakage_risks=[
                "Cross-slice leakage: Multiple slices from one subject in both train and test.",
                "Longitudinal session leakage: Baseline scan in train and 12-month follow-up in test.",
                "Scanner-site batch effects: Certain scanner manufacturers correlating with disease cohorts.",
            ],
            setup_steps=[
                "1. Download approved research cohort (e.g. ADNI/OASIS) or formatted dataset.",
                "2. Create folder layout at dataset/alzheimers/{train,val,test}/{class_name}/ with subject-level splitting.",
                "3. Train task-specific architecture with T1 preprocessing: python -m model.train_alzheimers.",
                "4. Save weights to backend/saved_models/axonova_alzheimers_best.keras.",
                "5. Platform will automatically detect weights, verify test split, and activate this task.",
            ],
        )

    def get_task_info(self) -> TaskInfo:
        return TaskInfo(
            task_id=self.task_id,
            name=self.name,
            short_title=self.short_title,
            category=self.category,
            status=self.get_status(),
            tagline=self.tagline,
            description=self.description,
            supported_scan_types=self.supported_scan_types,
            required_sequences=self.required_sequences,
            supported_orientations=self.supported_orientations,
            supported_formats=self.supported_formats,
            class_labels=self.get_class_labels(),
            model_loaded=self.is_ready(),
            model_name=None,
            model_version=None,
            input_shape=None,
            trainable_parameters=None,
            evaluation_available=False,
            overall_accuracy=None,
            limitations=self.limitations,
            disclaimer=self.disclaimer,
            setup_guide=self.get_setup_guide(),
        )

    def get_model_info(self) -> Dict[str, Any]:
        return {
            "loaded": False,
            "task_id": self.task_id,
            "model_name": None,
            "training_status": "Dataset/model setup required",
            "supported_classes": [],
            "supported_scan_type": "MRI",
            "evaluation_available": False,
            "disclaimer": self.disclaimer,
            "setup_guide": self.get_setup_guide().model_dump(),
        }

    def get_evaluation(self) -> Dict[str, Any]:
        return {
            "evaluated": False,
            "task_id": self.task_id,
            "reason": "Model weights and held-out test evaluation not conducted yet.",
            "disclaimer": self.disclaimer,
        }

    def get_dataset_info(self) -> Dict[str, Any]:
        return {
            "available": False,
            "task_id": self.task_id,
            "dataset_name": "Alzheimer's Disease Brain MRI Dataset",
            "source": "ADNI / OASIS (Pending Setup)",
            "total_images": 0,
            "class_distribution": {},
            "split_counts": {},
            "disclaimer": self.disclaimer,
            "setup_guide": self.get_setup_guide().model_dump(),
        }

    def predict(
        self,
        file_bytes: bytes,
        scan_type: str,
        orientation: str,
        filename: str = "uploaded_scan.jpg",
    ) -> Dict[str, Any]:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail=(
                "Task 'Alzheimer’s Disease MRI Classification' is not enabled. "
                "Dataset and trained model checkpoint are required. "
                "Simulated or placeholder predictions are strictly prohibited."
            ),
        )
